package com.cloudservice.gdpr.controller;

import org.springframework.batch.core.JobExecution;
import org.springframework.batch.core.explore.JobExplorer;
import org.springframework.http.ResponseEntity;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/batch/gdpr-exports")
public class BatchExportController {

    private final JobExplorer jobExplorer;

    public BatchExportController(JobExplorer jobExplorer) {
        this.jobExplorer = jobExplorer;
    }

    @GetMapping("/{jobExecutionId}/artifact")
    public ResponseEntity<String> getExportDownloadUrl(
            @PathVariable Long jobExecutionId,
            Authentication authentication) {
        JobExecution execution = jobExplorer.getJobExecution(jobExecutionId);
        if (execution == null) {
            return ResponseEntity.notFound().build();
        }
        String ownerId = execution.getJobParameters().getString("targetUserId");
        if (ownerId == null || !ownerId.equals(authentication.getName())) {
            throw new AccessDeniedException("Access to export archive belonging to another user is forbidden");
        }
        String downloadS3Url = (String) execution.getExecutionContext().get("downloadUrl");
        return ResponseEntity.ok(downloadS3Url);
    }
}
